// Skia side of the CPU draw layer tests (task D5: skcpu::Draw / SkBitmapDevice): runs the case
// script crates/skia-rust-raster/src/draw_tests/cases.txt (generated by oracle/draw/gen_cases.py)
// through a real SkBitmapDevice (and, for `devmask` / `pathcov`, a directly built skcpu::Draw)
// and prints hashes of the pixels. The Rust test interprets the same script and must print the
// same lines.
//
// Build and run (Windows): oracle/draw/build.ps1 (one dump per CPU code path).
//
// SCRIPT GRAMMAR. Line oriented; blank lines and lines starting with '#' are ignored; tokens are
// separated by single spaces; floats are decimal text parsed with strtof; ints are decimal;
// colors are 8 hex digits AARRGGBB meaning an SkColor (unpremultiplied).
//
//   case NAME          start a case; state reset (no device, identity ctm, default SkPaint,
//                      fresh clip stack)
//   device W H CT AT CS [PAD]
//       CT: n32 a8 gray8 rgb565 argb4444 rgbaf16 rgbaf32 rgba1010102 (n32 = kN32_SkColorType)
//       AT: premul|opaque|unpremul; for color types that are always opaque (gray8, rgb565) the
//           alpha type is forced to opaque, as SkBitmapDevice::Create does. The SkBitmap then
//           canonicalises the alpha type (SkColorTypeValidateAlphaType, e.g. a8 unpremul ->
//           premul).
//       CS: srgb|linear|none (SkColorSpace::MakeSRGB / MakeSRGBLinear / nullptr)
//       PAD: extra pixels of row padding (default 0); rowBytes = (W + PAD) * bytesPerPixel.
//       The storage is zero-initialised and installed with SkBitmap::installPixels; the device is
//       `SkBitmapDevice(bitmap, SkSurfaceProps())`. If installPixels fails, prints `NAME skip`
//       and ignores the lines up to the next `case`.
//   erase AARRGGBB     bitmap.eraseColor(SkColor)
//   noise SEED         for every pixel (x, y) of the W x H area, k = y*W + x:
//                      bitmap.erase(SkColorSetARGB(R(SEED,3k)&255, R(SEED,3k+1)&255,
//                      R(SEED,3k+2)&255, (R(SEED,3k)>>8)&255), SkIRect::MakeXYWH(x, y, 1, 1))
//   save | restore     device->pushClipStack() / popClipStack() (restore without save: ignored)
//   ctm id | ctm M00 M01 M02 M10 M11 M12 M20 M21 M22
//                      device->setLocalToDevice(SkM44(SkMatrix::MakeAll(...)))
//   cliprect L T R B OP AA                       OP intersect|diff, AA 0|1
//   cliprrect L T R B RX RY OP AA                SkRRect::MakeRectXY
//   cliprrect4 L T R B X0 Y0 X1 Y1 X2 Y2 X3 Y3 OP AA   setRectRadii (UL UR LR LL)
//   clippath OP AA PATH
//   clipregion OP N L T R B ...                  union (SkRegion::op kUnion) of N int rects
//   replaceclip L T R B                          device->replaceClip(SkIRect)
//   paint KEY=VALUE ...    the current paint becomes a fresh SkPaint with the keys applied in
//                          order. Keys: color=AARRGGBB aa=0|1 dither=0|1
//                          style=fill|stroke|strokefill width=F cap=butt|round|square
//                          join=miter|round|bevel miter=F blend=N (SkBlendMode 0..28)
//                          shader=solid:AARRGGBB (SkShaders::Color)
//                          pe=dash:I0,I1,...@PHASE (SkDashPathEffect::Make)
//                          pe=corner:R (SkCornerPathEffect::Make)
//                          pe=sum_dash_corner:ON,OFF@PHASE:R  (MakeSum(dash, corner))
//                          pe=compose_corner_dash:ON,OFF@PHASE:R (MakeCompose(corner, dash))
//   drawpaint
//   rect L T R B | oval L T R B | rrect L T R B RX RY
//   rrect4 L T R B X0 Y0 X1 Y1 X2 Y2 X3 Y3
//   drrect oL oT oR oB oRX oRY iL iT iR iB iRX iRY   (both MakeRectXY) device->drawDRRect
//   region N L T R B ...                         device->drawRegion(union of N int rects)
//   path PATH                                    device->drawPath
//   points MODE N X Y ...                        MODE points|lines|polygon
//   devmask CLIP FMT ML MT MR MB SEED
//       skcpu::Draw on the device's pixels (accessPixels), fCTM = &device->localToDevice(),
//       fRC = SkRasterClip from CLIP, fProps = nullptr; draw.drawDevMask(mask, paint, nullptr).
//       CLIP: rect:L,T,R,B (ints, SkRasterClip(SkIRect)) or oval:L,T,R,B (floats,
//       SkRasterClip(SkPath::Oval(rect), SkIRect(0,0,W,H), true)).
//       FMT a8|bw|lcd16; bounds (ML,MT,MR,MB); rowBytes = a8: align4(w), bw: align4((w+7)>>3),
//       lcd16: align4(w*2); byte i of the image (i < rowBytes*h) = R(SEED, i) & 0xFF (lcd16
//       values are little-endian pairs of these bytes).
//   pathcov CLIP PATH  same Draw; draw.drawPathCoverage(path, paint) (a8 devices only)
//   hash LABEL         prints `NAME LABEL HASH`
//   query LABEL        prints `NAME LABEL q empty=E rect=R aa=A wide=W bounds=L,T,R,B`
//                      (isClipEmpty, isClipRect, isClipAntiAliased, isClipWideOpen,
//                      devClipBounds)
//   readpixels LABEL X Y W H CT AT CS
//       dst pixmap (rowBytes = W*bpp, bytes initialised to 0xA5), ok = device->readPixels(dst,
//       X, Y); prints `NAME LABEL rp ok=0|1 HASH` (HASH of the dst, also when !ok)
//   writepixels LABEL X Y W H CT AT CS SEED
//       src bitmap (zeroed storage, rowBytes = W*bpp, then `noise SEED` on it), ok =
//       device->writePixels(src.pixmap(), X, Y); prints `NAME LABEL wp ok=0|1`
//   end                prints `NAME end HASH`
//
// PATH = FILL VERB...: FILL w|e|iw|ie (winding, evenodd, inverse winding, inverse evenodd), verbs
// `M x y`, `L x y`, `Q x1 y1 x y`, `K x1 y1 x y w` (conic), `C x1 y1 x2 y2 x y`, `Z`; built with
// SkPathBuilder (setFillType, the verbs, detach()).
//
// HASH: FNV-1a 64 (offset 0xcbf29ce484222325, prime 0x100000001b3) over the W x H pixels row by
// row, without row padding, printed as 16 lowercase hex digits. n32 pixels contribute the bytes
// A, R, G, B (SkGetPackedA32/R32/G32/B32), so the hash does not depend on the N32 byte order;
// other color types contribute their stored bytes (little endian).
//
// R(seed, k) = hash32(seed * 0x9E3779B1 + k * 0x85EBCA77 + 0x165667B1) (uint32 wrap-around),
// hash32 as in oracle/rp-builder/d4_blitters.cpp.

